  let r2 = 1.0 - abs(2.0 * ocean_noise(q * 2.3 - vec2f(t * 0.07, t * 0.02)) - 1.0);
  return 0.7 * pow(r1, 8.0) + 0.4 * pow(r2, 10.0);
