    lightAdd(v, power * (tEnd - t));
    t = tEnd;
    if (t >= len) { break; }
    if (tNext.x <= tNext.y && tNext.x <= tNext.z) { v.x += stepDir.x; tNext.x += tDelta.x; }
    else if (tNext.y <= tNext.z) { v.y += stepDir.y; tNext.y += tDelta.y; }
